def transform_final(grid):
    rows = len(grid)
    if rows == 0:
        return grid

    cols = len(grid[0])
    result = [[0 for _ in range(cols)] for _ in range(rows)]

    # Find source row
    source_row = None
    for r in range(rows):
        non_0_1_count = sum(1 for v in grid[r] if v not in [0, 1])
        if non_0_1_count > 0:
            source_row = r
            break

    if source_row is None:
        return result

    non_0_1_values = [v for v in grid[source_row] if v not in [0, 1]]
    is_multi = len(non_0_1_values) >= 2

    # Create beams
    for c in range(cols):
        val = grid[source_row][c]
        if val not in [0, 1]:
            if val == 2:
                beam_len = 4
            elif val == 8:
                beam_len = 3
            else:
                continue

            for i in range(1, beam_len + 1):
                beam_row = source_row - i
                if 0 <= beam_row < rows:
                    if i == 1:
                        result[beam_row][c] = val
                    elif is_multi and i == beam_len:
                        result[beam_row][c] = val
                    else:
                        result[beam_row][c] = 1

    return result

