def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0 for _ in range(cols)] for _ in range(rows)]

    source_row = None
    for ri in range(rows):
        n = sum(1 for v in grid[ri] if v not in [0, 1])
        if n > 0:
            source_row = ri
            break

    if source_row is None:
        return result

    source_ones = [(c, 1) for c, v in enumerate(grid[source_row]) if v == 1]
    values = [(c, v) for c, v in enumerate(grid[source_row]) if v not in [0, 1]]
    is_multi = len(values) >= 2

    if is_multi:
        sim_source_row = source_row - 1
    else:
        sim_source_row = source_row

    for c, val in values:
        if val == 2:
            pattern_len = 4 if is_multi else 5
            start = sim_source_row - (pattern_len - 1) if is_multi else source_row - (pattern_len - 1)
            pattern = [2, 1, 1, 2] if is_multi else [2, 1, 1, 1, 2]
            for i, p in enumerate(pattern):
                result[start + i][c] = p
        elif val == 8:
            pattern_len = 3 if is_multi else 4
            start = sim_source_row - (pattern_len - 1) if is_multi else source_row - (pattern_len - 1)
            pattern = [8, 1, 8] if is_multi else [8, 1, 1, 8]
            for i, p in enumerate(pattern):
                result[start + i][c] = p

    for c, one in source_ones:
        if is_multi:
            result[sim_source_row][c] = 1
        else:
            result[source_row][c] = 1

    return result

